/* The tools a OnePage's signups are sent to as they happen (round 40): new `onepage_integrations`, one row per store and tool (Mailchimp, Kit, beehiiv, Zapier, Make, Google Sheets or a webhook of the creator's own), holding the chosen list or form (`config`), the API key or the webhook address and signing secret sealed by the server (`secret_ciphertext`, AES-256-GCM, never readable by a browser), and what happened to the signups sent (`sent_count`, `failed_count`, `last_sent_at`, `last_error`, `last_error_at`). Written and read only by the server for the signed in owner (/api/onepage/integrations) and by the signup routes (lib/onepage/integrations/deliver-server): row level security on, nothing granted to anon or authenticated, so no key can be read from a browser even by its owner. `onepage_integration_note` counts one send in one step, so two signups at once both count; only the service role may run it. New table and function only; no existing row changes. Until it runs, the editor's Settings › Integrations says this part is needed and signups are kept on Storelib as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.onepage_integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, provider text NOT NULL CHECK (provider IN ('mailchimp', 'kit', 'beehiiv', 'zapier', 'make', 'sheets', 'webhook')), status text NOT NULL DEFAULT 'connected' CHECK (status IN ('connected', 'paused')), account_label text CHECK (account_label IS NULL OR length(account_label) <= 200), config jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(config) = 'object'), secret_ciphertext text CHECK (secret_ciphertext IS NULL OR secret_ciphertext LIKE 'v1.%'), sent_count integer NOT NULL DEFAULT 0 CHECK (sent_count >= 0), failed_count integer NOT NULL DEFAULT 0 CHECK (failed_count >= 0), last_sent_at timestamptz, last_error text CHECK (last_error IS NULL OR length(last_error) <= 500), last_error_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT onepage_integrations_one_per_tool UNIQUE (creator_id, provider));
CREATE INDEX IF NOT EXISTS onepage_integrations_connected_idx ON public.onepage_integrations (creator_id) WHERE status = 'connected';
ALTER TABLE public.onepage_integrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.onepage_integrations FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.onepage_integrations TO service_role;
CREATE OR REPLACE FUNCTION public.onepage_integration_note(p_id uuid, p_ok boolean, p_error text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $fn$ UPDATE public.onepage_integrations SET sent_count = sent_count + CASE WHEN p_ok THEN 1 ELSE 0 END, failed_count = failed_count + CASE WHEN p_ok THEN 0 ELSE 1 END, last_sent_at = CASE WHEN p_ok THEN now() ELSE last_sent_at END, last_error = CASE WHEN p_ok THEN NULL ELSE left(coalesce(p_error, 'Not sent.'), 500) END, last_error_at = CASE WHEN p_ok THEN NULL ELSE now() END, updated_at = now() WHERE id = p_id; $fn$;
REVOKE ALL ON FUNCTION public.onepage_integration_note(uuid, boolean, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.onepage_integration_note(uuid, boolean, text) TO service_role;
notify pgrst, 'reload schema';
